      <section class="iq-card block"><div class="block-title"><div><h3>选择章节</h3><p>可多选；点击“选择全部章节”会把10个章节全部标为已选择。</p></div><button class="highlight-btn" :class="{selected:allChaptersSelected}" @click="selectAllChapters">{{allChaptersSelected?'已选择全部章节':'选择全部章节'}}</button></div>
        <div class="chapter-grid"><button v-for="n in 10" :key="n" class="chapter" :class="{active:form.chapters.includes(n)}" @click="toggleChapter(n)"><b>第{{n}}章</b><strong>{{getChapterName(n)}}</strong><span>{{form.chapters.includes(n)?'已选择':'点击选择'}}</span></button></div>
        <button class="iq-btn iq-btn-primary inspect" :disabled="checking" @click="loadPlans">{{checking?'正在分析题库...':'查看本章节可行方案'}}</button>
      </section>

      <section v-if="report" class="iq-card block plans-block"><div class="block-title"><div><h3>推荐练习方案</h3><p>这些方案已按当前章节库存计算，可以直接使用，不需要反复试数字。</p></div><button class="highlight-btn" @click="openManual">我要手动设置</button></div>
        <div v-if="report.plans?.length" class="plan-grid"><button v-for="plan in report.plans" :key="plan.id" class="plan" :class="{active:selectedPlan?.id===plan.id&&mode==='preset'}" @click="selectPlan(plan)"><span class="plan-tag">可直接开始</span><h4>{{plan.name}}</h4><p>{{plan.description}}</p><div><b>{{plan.questionCount}}</b>题 <em>可用{{plan.totalAvailable}}题</em></div></button></div>
