        <div v-if="mode==='manual'" class="manual"><div class="manual-head"><div><h4>手动设置</h4><p>适合想指定知识点或题型的情况。系统仍会先检查库存。</p></div><button class="text-btn" @click="mode='preset'">返回推荐方案</button></div>
          <div class="manual-grid"><label><span>知识点关键词</span><input v-model.trim="form.knowledgeKeyword" class="iq-input" placeholder="输入“循环”可匹配“循环结构”等知识点"></label><label><span>题目数量</span><input v-model.number="form.questionCount" class="iq-input" type="number" min="5" max="50"></label></div>
          <div class="types"><b>题型</b><label v-for="t in types" :key="t.value"><input v-model="form.questionTypes" type="checkbox" :value="t.value">{{t.label}}</label></div><button class="iq-btn iq-btn-secondary" @click="checkManual">检查手动条件</button>
        </div>
        <div v-if="mode==='manual'&&manualReport" class="report" :class="manualReport.enough?'ok':'bad'"><h4>{{manualReport.message}}</h4><div class="stock"><span v-for="d in manualReport.byDifficulty" :key="d.difficulty">{{d.difficulty}}级 {{d.label}} <b>{{d.total}}题</b></span></div><p v-if="form.knowledgeKeyword">实际匹配：{{manualReport.knowledgePoints?.join('、')||'没有匹配知识点'}}</p><div v-if="!manualReport.enough" class="fixes"><b>一键调整：</b><button v-for="s in manualReport.suggestions" :key="s.code" @click="apply(s)">{{s.text}}</button></div></div>
        <div class="start-bar"><div><b>{{mode==='preset'?(selectedPlan?selectedPlan.name:'请选择一个方案'):'手动设置'}}</b><span>{{ready?'条件已通过检查，可以开始':'完成选择并通过库存检查后才能开始'}}</span></div><button class="iq-btn iq-btn-primary" :disabled="!ready||starting" @click="start">{{starting?'正在准备...':'开始自适应练习'}}</button></div>
      </section>
      <div v-if="errorText" class="error">{{errorText}}</div>
