    <section v-else-if="phase==='question'&&question" class="iq-card question-card"><div class="progress-line"><span :style="{width:`${progress.answered/progress.total*100}%`}"></span></div><div class="question-head"><div><small>第 {{progress.answered+1}} / {{progress.total}} 题</small><div class="question-level"><h2>{{question.difficulty}}级 · {{question.difficultyLabel}}</h2><span class="difficulty-stars" :aria-label="`${question.difficulty} 星难度`"><b v-for="n in 5" :key="n" :class="{active:n<=Number(question.difficulty)}">★</b></span></div></div><button class="iq-btn iq-btn-secondary" @click="reset">退出</button></div><div class="meta"><span>{{getChapterLabel(question.chapter)}}</span><span>{{typeName(question.type)}}</span><span>{{question.knowledgePoint||'综合知识点'}}</span></div><div v-if="fallback" class="notice">{{fallback}}</div><h3 class="content">{{question.content}}</h3>
      <div v-if="options.length" class="options"><label v-for="o in options" :key="o.key" :class="{selected:selected.includes(o.key)}"><input :type="question.type===3?'checkbox':'radio'" :value="o.key" v-model="answer">{{o.key}}. {{o.text}}</label></div><textarea v-else-if="Number(question.type)>=5" v-model="textAnswer" class="iq-input subjective-input" rows="8" placeholder="请写出结论、关键步骤和必要说明"></textarea><input v-else v-model="textAnswer" class="iq-input" placeholder="请输入答案"><button class="iq-btn iq-btn-primary submit" :disabled="submitting||!!feedback" @click="submit">{{submitting?'正在评阅...':'提交本题'}}</button>
