    </section>
    <section v-else class="iq-card finish"><span>练习完成</span><h2>{{summary.accuracy}}分</h2><p>完成{{summary.answered}}题，答对{{summary.correct}}题，最终到达{{summary.difficulty}}级。</p><div class="road">难度轨迹：{{summary.trajectory.join(' → ')||'1'}}</div><button class="iq-btn iq-btn-primary" @click="reset">选择新的练习</button></section>
  </div>
</template>
<script setup>
