-top:18px;padding:18px;background:#f8fafc;border-radius:14px}.manual-grid{display:grid;grid-template-columns:2fr 1fr;gap:12px}.manual-grid label{display:grid;gap:6px}.types{display:flex;gap:15px;margin:15px 0}.report,.error,.notice,.feedback{padding:16px;margin-top:15px;border-radius:12px}.report.ok,.feedback.right{background:#ecfdf5;color:#047857}.report.bad,.error,.feedback.wrong{background:#fef2f2;color:#b91c1c}.stock,.fixes{display:flex;flex-wrap:wrap;gap:8px}.stock span,.fixes button{padding:7px 9px;background:white;border:1px solid #e2e8f0;border-radius:8px}.start-bar{margin-top:20px;padding:16px 18px;background:#eef2ff;border-radius:12px}.start-bar div{display:grid}.start-bar span{font-size:12px;color:#64748b}.empty-plan{text-align:center;padding:30px;background:#fff7ed;border-radius:12px}.question-card{padding:28px;max-width:900px;margin:auto}.progress-line{height:7px;background:#e2e8f0;border-radius:5px}.progress-line span{display:block;height:100%;background:#6366f1;border-radius:5px}.question-head{margin-top:18px}.question-head h2{margin:4px 0}.meta{display:flex;gap:8px}.meta span{padding:5px 9px;border-radius:12px;background:#eef2ff;color:#4338ca}.notice{background:#fff7ed;color:#9a3412}.content{line-height:1.8;margin:25px 0}.options{display:grid;gap:10px}.options label{padding:14px;border:1px solid #e2e8f0;border-radius:10px}.options label.selected{background:#eef2ff;border-color:#6366f1}.submit{margin-top:18px}.adjustment{padding:10px;background:white;border-radius:8px}.recent{margin:12px 0}.recent span{display:inline-grid;place-items:center;width:26px;height:26px;margin-left:5px;border-radius:50%;color:white}.yes{background:#16a34a}.no{background:#ef4444}.finish{max-width:700px;padding:50px;text-align:center;margin:auto}.finish h2{font-size:60px;color:#4f46e5;margin:8px}.road{margin:20px;padding:15px;background:#f1f5f9;border-radius:10px}@media(max-width:850px){.chapter-grid{grid-template-columns:repeat(2,1fr)}.plan-grid{grid-template-columns:1fr 1fr}